// SPDX-License-Identifier: BSL-1.1
pragma solidity ^0.8.0;

import {IERC20} from "@crane/contracts/interfaces/IERC20.sol";
import {IAllowanceTransfer} from "@crane/contracts/interfaces/protocols/utils/permit2/IAllowanceTransfer.sol";
import {IUniswapV4SeBufferHook} from "contracts/hooks/uniswap/v4/interfaces/IUniswapV4SeBufferHook.sol";
import {
    TestBase_UniswapV4SingleStandardExchangeBufferConstantProductHook as TestBase
} from "contracts/hooks/uniswap/v4/standardExchange/constantProduct/single/TestBase_UniswapV4SingleStandardExchangeBufferConstantProductHook.sol";

/// @title UniswapV4SingleStandardExchangeBufferConstantProductHook_FeeCapital_Test
/// @notice Incoming liquidity is excluded from protocol growth fees on the registered CP package.
contract UniswapV4SingleStandardExchangeBufferConstantProductHook_FeeCapital_Test is TestBase {
    /// @notice Start from a fee-on reserve with no accrued swap or yield growth.
    function setUp() public override {
        super.setUp();
        _enableProtocolFee(0.05e18);
        _seedLiveLiquidity();
    }

    /// @notice Balanced raw/pair capital mints only depositor LP and matches the preview exactly.
    function test_balancedDeposit_newCapitalDoesNotMintProtocolFee() public {
        uint256 feeBefore = IERC20(hook).balanceOf(_feeTo());
        _depositPairAndCheckPreview(20 ether, 20 ether);
        assertEq(IERC20(hook).balanceOf(_feeTo()), feeBefore, "new capital is not growth");
    }

    /// @notice Balanced raw/SE-share capital does not create a growth fee.
    function test_balancedSeShares_newCapitalDoesNotMintProtocolFee() public {
        uint256 shares = _mintSeSharesToUser(20 ether);
        uint256 feeBefore = IERC20(hook).balanceOf(_feeTo());
        _depositSharesAndCheckPreview(20 ether, shares);
        assertEq(IERC20(hook).balanceOf(_feeTo()), feeBefore, "incoming SE shares are not growth");
    }

    /// @notice The generic proportional intake accrues fees before pulling its two legs.
    function test_joinProportional_newCapitalDoesNotMintProtocolFee() public {
        uint256[] memory amounts = new uint256[](2);
        amounts[0] = 20 ether;
        amounts[1] = 20 ether;
        IUniswapV4SeBufferHook h = IUniswapV4SeBufferHook(hook);
        (uint256 preview, uint256[] memory usedPreview) = h.previewJoinProportional(amounts);
        uint256 feeBefore = IERC20(hook).balanceOf(_feeTo());
        vm.prank(user);
        (uint256 minted, uint256[] memory used) = h.joinProportional(amounts, user, preview, block.timestamp);
        assertEq(minted, preview, "generic join preview");
        assertEq(used, usedPreview, "generic join amounts");
        assertEq(IERC20(hook).balanceOf(_feeTo()), feeBefore, "generic capital is not growth");
    }

    /// @notice The generic SE-share intake also excludes both incoming legs from growth.
    function test_joinUnbalancedSeShares_newCapitalDoesNotMintProtocolFee() public {
        uint256 shares = _mintSeSharesToUser(20 ether);
        address[] memory tokens = new address[](2);
        tokens[0] = address(rawToken);
        tokens[1] = se;
        uint256[] memory amounts = new uint256[](2);
        amounts[0] = 20 ether;
        amounts[1] = shares;
        IUniswapV4SeBufferHook h = IUniswapV4SeBufferHook(hook);
        uint256 preview = h.previewJoinUnbalanced(tokens, amounts);
        uint256 feeBefore = IERC20(hook).balanceOf(_feeTo());
        vm.prank(user);
        uint256 minted = h.joinUnbalanced(tokens, amounts, user, preview, block.timestamp);
        assertEq(minted, preview, "SE-share generic preview");
        assertEq(IERC20(hook).balanceOf(_feeTo()), feeBefore, "generic SE capital is not growth");
    }

    /// @notice Real Permit2 allowance intake preserves the same pre-intake fee boundary.
    function test_permit2Allowance_newCapitalDoesNotMintProtocolFee() public {
        uint256 feeBefore = IERC20(hook).balanceOf(_feeTo());
        (uint256 preview, uint256 used0Preview, uint256 used1Preview) = single.previewDeposit(20 ether, 20 ether);
        vm.startPrank(user);
        rawToken.approve(address(permit2), type(uint256).max);
        pairToken.approve(address(permit2), type(uint256).max);
        IAllowanceTransfer(address(permit2)).approve(address(rawToken), hook, type(uint160).max, type(uint48).max);
        IAllowanceTransfer(address(permit2)).approve(address(pairToken), hook, type(uint160).max, type(uint48).max);
        (uint256 minted, uint256 used0, uint256 used1) =
            single.depositWithPermit2Allowance(20 ether, 20 ether, user, preview, block.timestamp);
        vm.stopPrank();
        assertEq(minted, preview, "Permit2 LP preview");
        assertEq(used0, used0Preview, "Permit2 currency0 preview");
        assertEq(used1, used1Preview, "Permit2 currency1 preview");
        assertEq(IERC20(hook).balanceOf(_feeTo()), feeBefore, "Permit2 capital is not growth");
    }

    /// @notice Single-sided raw intake does not count the just-pulled raw inventory as prior growth.
    function test_singleRawDeposit_newCapitalDoesNotMintPriorGrowthFee() public {
        uint256 feeBefore = IERC20(hook).balanceOf(_feeTo());
        vm.prank(user);
        uint256 minted = single.depositSingle(address(rawToken), 5 ether, user, 0, block.timestamp);
        assertGt(minted, 0, "single deposit completes");
        assertEq(IERC20(hook).balanceOf(_feeTo()), feeBefore, "single raw input is not prior growth");
    }

    /// @notice Previously accrued yield earns the same protocol fee regardless of incoming deposit size.
    function test_realGrowth_feeIndependentOfNewCapitalAndPreviewMatches() public {
        _addYield(20 ether);
        uint256 feeBefore = IERC20(hook).balanceOf(_feeTo());
        uint256 snapshot = vm.snapshotState();
        _depositPairAndCheckPreview(10 ether, 11 ether);
        uint256 smallDepositFee = IERC20(hook).balanceOf(_feeTo()) - feeBefore;
        assertGt(smallDepositFee, 0, "real yield accrues protocol fee");

        assertTrue(vm.revertToState(snapshot), "restore identical accrued growth");
        _depositPairAndCheckPreview(100 ether, 110 ether);
        assertEq(IERC20(hook).balanceOf(_feeTo()) - feeBefore, smallDepositFee, "fee depends only on prior growth");
    }

    /// @notice SE-share intake preserves the same positive fee for existing yield at both deposit sizes.
    function test_realGrowth_seSharesFeeIndependentOfNewCapitalAndPreviewMatches() public {
        _mintSeSharesToUser(100 ether);
        _addYield(30 ether);
        uint256 feeBefore = IERC20(hook).balanceOf(_feeTo());
        uint256 snapshot = vm.snapshotState();
        _depositSharesAndCheckPreview(10 ether, 10 ether);
        uint256 smallDepositFee = IERC20(hook).balanceOf(_feeTo()) - feeBefore;
        assertGt(smallDepositFee, 0, "existing SE yield earns fee");

        assertTrue(vm.revertToState(snapshot), "restore identical SE growth");
        _depositSharesAndCheckPreview(100 ether, 100 ether);
        assertEq(IERC20(hook).balanceOf(_feeTo()) - feeBefore, smallDepositFee, "SE fee excludes new capital");
    }

    /// @notice Exact-out admission uses the same pending-fee quote as the external preview, before pulling.
    function test_realGrowth_exactOutQuoteDoesNotCountPendingFeeTwice() public {
        _addYield(20 ether);
        uint256 preview = single.previewDepositSingle(address(rawToken), 5 ether);
        assertGt(preview, 0, "nonzero single-deposit quote");
        uint256 feeBefore = IERC20(hook).balanceOf(_feeTo());
        vm.prank(user);
        rawToken.approve(hook, 0);

        // The quoted bound must reject before a token pull can fail for missing approval.
        vm.expectRevert(abi.encodeWithSignature("InsufficientLpOut()"));
        vm.prank(user);
        IUniswapV4SeBufferHook(hook)
            .joinSingleAssetExactOut(address(rawToken), preview + 1, user, 5 ether, block.timestamp);
        assertEq(IERC20(hook).balanceOf(_feeTo()), feeBefore, "rejected quote leaves fee accrual untouched");
    }

    /// @notice Exact-out intake and direct intake charge identical accrued fees from identical state.
    function test_realGrowth_exactOutAccruesOnceAndMatchesDirectIntake() public {
        _addYield(20 ether);
        uint256 feeBefore = IERC20(hook).balanceOf(_feeTo());
        uint256 lpBefore = IERC20(hook).balanceOf(user);
        uint256 rawBefore = rawToken.balanceOf(user);
        uint256 preview = single.previewDepositSingle(address(rawToken), 5 ether);
        uint256 snapshot = vm.snapshotState();
        vm.prank(user);
        uint256 directLp = single.depositSingle(address(rawToken), 5 ether, user, 0, block.timestamp);
        uint256 directFee = IERC20(hook).balanceOf(_feeTo()) - feeBefore;
        assertGt(directFee, 0, "existing growth earns fee");
        assertGt(directLp, 0, "direct single intake completes");

        assertTrue(vm.revertToState(snapshot), "restore identical single-intake growth");
        uint256 sharesMin = preview < directLp ? preview : directLp;
        assertGt(sharesMin, 0, "positive exact-out minimum");
        vm.prank(user);
        uint256 spent = IUniswapV4SeBufferHook(hook)
            .joinSingleAssetExactOut(address(rawToken), sharesMin, user, 5 ether, block.timestamp);
        assertEq(spent, 5 ether, "exact-out uses configured maximum input");
        assertEq(rawBefore - rawToken.balanceOf(user), spent, "exact-out raw debit");
        assertEq(IERC20(hook).balanceOf(user) - lpBefore, directLp, "same intake produces same LP");
        assertEq(IERC20(hook).balanceOf(_feeTo()) - feeBefore, directFee, "pending growth fee minted once");
    }

    /// @dev Assert both token usage and LP issuance against the public pre-intake quote.
    function _depositPairAndCheckPreview(uint256 rawAmount, uint256 pairAmount) internal {
        uint256 a0 = _amountForCurrency(single.currency0(), rawAmount, pairAmount);
        uint256 a1 = _amountForCurrency(single.currency1(), rawAmount, pairAmount);
        (uint256 preview, uint256 u0Preview, uint256 u1Preview) = single.previewDeposit(a0, a1);
        vm.prank(user);
        (uint256 minted, uint256 u0, uint256 u1) = single.deposit(a0, a1, user, preview, block.timestamp);
        assertEq(minted, preview, "raw/pair LP preview");
        assertEq(u0, u0Preview, "raw/pair currency0 usage");
        assertEq(u1, u1Preview, "raw/pair currency1 usage");
    }

    /// @dev Assert the SE-share intake quote on the deployed hook proxy.
    function _depositSharesAndCheckPreview(uint256 rawAmount, uint256 shareAmount) internal {
        (uint256 preview, uint256 rawPreview, uint256 sharePreview) =
            single.previewDepositWithSeShares(rawAmount, shareAmount);
        vm.prank(user);
        (uint256 minted, uint256 usedRaw, uint256 usedShares) =
            single.depositWithSeShares(rawAmount, shareAmount, user, preview, block.timestamp);
        assertEq(minted, preview, "SE-share LP preview");
        assertEq(usedRaw, rawPreview, "SE-share raw usage");
        assertEq(usedShares, sharePreview, "SE-share usage");
    }

    /// @dev Use the existing yield-bearing ERC4626 fixture without mocking the SE or fee oracle.
    function _addYield(uint256 amount) internal {
        pairToken.mint(address(this), amount);
        pairToken.approve(address(pairProtocolVault), amount);
        pairProtocolVault.simulateYield(amount);
    }
}

// SPDX-License-Identifier: BSL-1.1
pragma solidity ^0.8.0;

import {IERC20} from "@crane/contracts/interfaces/IERC20.sol";
import {IERC165} from "@crane/contracts/interfaces/IERC165.sol";
import {IFacet} from "@crane/contracts/interfaces/IFacet.sol";
import {IDiamond} from "@crane/contracts/interfaces/IDiamond.sol";
import {IDiamondLoupe} from "@crane/contracts/interfaces/IDiamondLoupe.sol";
import {IHooks} from "@crane/contracts/protocols/dexes/uniswap/v4/interfaces/IHooks.sol";
import {IStandardExchangeIn} from "@crane/contracts/interfaces/IStandardExchangeIn.sol";
import {PoolKey} from "@crane/contracts/protocols/dexes/uniswap/v4/types/PoolKey.sol";
import {Currency} from "@crane/contracts/protocols/dexes/uniswap/v4/types/Currency.sol";
import {PoolId, PoolIdLibrary} from "@crane/contracts/protocols/dexes/uniswap/v4/types/PoolId.sol";
import {TickMath} from "@crane/contracts/protocols/dexes/uniswap/v4/libraries/TickMath.sol";
import {Hooks} from "@crane/contracts/protocols/dexes/uniswap/v4/libraries/Hooks.sol";
import {CustomRevert} from "@crane/contracts/protocols/dexes/uniswap/v4/libraries/CustomRevert.sol";
import {Proxy} from "@crane/contracts/proxies/Proxy.sol";
import {Vm} from "forge-std/Vm.sol";

import {IStandardVault} from "contracts/interfaces/IStandardVault.sol";
import {IBasicVault} from "contracts/interfaces/IBasicVault.sol";
import {SimpleMintableERC20} from "contracts/test/stubs/SimpleMintableERC20.sol";
import {SimpleYieldERC4626} from "contracts/test/stubs/SimpleYieldERC4626.sol";
import {
    TestBase_UniswapV4SingleStandardExchangeBufferConstantProductHook as TestBase
} from "contracts/hooks/uniswap/v4/standardExchange/constantProduct/single/TestBase_UniswapV4SingleStandardExchangeBufferConstantProductHook.sol";
import {
    IUniswapV4SingleStandardExchangeBufferConstantProductHook as IHook
} from "contracts/hooks/uniswap/v4/standardExchange/constantProduct/single/interfaces/IUniswapV4SingleStandardExchangeBufferConstantProductHook.sol";
import {
    IUniswapV4HookStagedPairInit
} from "contracts/hooks/uniswap/v4/interfaces/IUniswapV4HookStagedPairInit.sol";
import {
    IUniswapV4SingleStandardExchangeBufferConstantProductHookPackage
} from "contracts/hooks/uniswap/v4/standardExchange/constantProduct/single/interfaces/IUniswapV4SingleStandardExchangeBufferConstantProductHookPackage.sol";
import {
    UniswapV4SingleStandardExchangeBufferConstantProductHookPairPoolLib as PairPoolLib
} from "contracts/hooks/uniswap/v4/standardExchange/constantProduct/single/UniswapV4SingleStandardExchangeBufferConstantProductHookPairPoolLib.sol";
import {
    UniswapV4SingleStandardExchangeBufferConstantProductHookBeforeInitializeLib as BeforeInitializeLib
} from "contracts/hooks/uniswap/v4/standardExchange/constantProduct/single/UniswapV4SingleStandardExchangeBufferConstantProductHookBeforeInitializeLib.sol";
import {
    UniswapV4SingleStandardExchangeBufferConstantProductHookSeTarget as SeTarget
} from "contracts/hooks/uniswap/v4/standardExchange/constantProduct/single/UniswapV4SingleStandardExchangeBufferConstantProductHookSeTarget.sol";
import {
    UniswapV4SingleStandardExchangeBufferConstantProductHookInitFacet
} from "contracts/hooks/uniswap/v4/standardExchange/constantProduct/single/facets/UniswapV4SingleStandardExchangeBufferConstantProductHookInitFacet.sol";
import {HookPkgArgsDecimalsLib} from "contracts/test/libs/HookPkgArgsDecimalsLib.sol";
import {
    UniswapV4SingleStandardExchangeBufferConstantProductHookDFPkg
} from "contracts/hooks/uniswap/v4/standardExchange/constantProduct/single/UniswapV4SingleStandardExchangeBufferConstantProductHookDFPkg.sol";

/**
 * @title UniswapV4SingleStandardExchangeBufferConstantProductHook_StagedInit_Test
 * @notice S43 bootstrap-only deploy plus one-door / finalize matrix.
 */
contract UniswapV4SingleStandardExchangeBufferConstantProductHook_StagedInit_Test is TestBase {
    using PoolIdLibrary for PoolKey;

    bytes32 internal constant PAIR_POOL_DEPLOYED_TOPIC =
        keccak256("PairPoolDeployed(address,address,address,bytes32)");

    function test_facetCuts_isBootstrapOnly() public view {
        IDiamond.FacetCut[] memory cuts = hookPkg.facetCuts();
        assertEq(cuts.length, 4);
        assertEq(cuts[0].facetAddress, address(multiStepOwnableFacet));
        assertEq(cuts[1].facetAddress, address(multiAssetBasicVaultFacet));
        assertEq(cuts[2].facetAddress, address(multiAssetStandardVaultFacet));
        assertEq(cuts[3].facetAddress, address(hookPkg));
        assertEq(uint8(cuts[0].action), uint8(IDiamond.FacetCutAction.Add));
        assertEq(uint8(cuts[1].action), uint8(IDiamond.FacetCutAction.Add));
        assertEq(uint8(cuts[2].action), uint8(IDiamond.FacetCutAction.Add));
        assertEq(uint8(cuts[3].action), uint8(IDiamond.FacetCutAction.Add));
        _assertSelectorEq(cuts[0].functionSelectors, multiStepOwnableFacet.facetFuncs());
        _assertSelectorEq(cuts[3].functionSelectors, IFacet(address(hookPkg)).facetFuncs());
    }

    function test_productionFacetCuts_eightAdds() public view {
        IDiamond.FacetCut[] memory cuts = hookPkg.productionFacetCuts();
        assertEq(cuts.length, 8);
        assertEq(cuts[0].facetAddress, address(hookPkg.SE_FACET()));
        assertEq(cuts[1].facetAddress, address(hookPkg.DEPOSIT_FACET()));
        assertEq(cuts[2].facetAddress, address(hookPkg.WITHDRAW_FACET()));
        assertEq(cuts[3].facetAddress, address(erc20Facet));
        assertEq(cuts[4].facetAddress, address(erc5267Facet));
        assertEq(cuts[5].facetAddress, address(erc2612Facet));
        assertEq(cuts[6].facetAddress, address(hookPkg.DEPOSIT_SINGLE_FACET()));
        assertEq(cuts[7].facetAddress, address(hookPkg.DEPOSIT_PREVIEW_FACET()));
        _assertSelectorEq(cuts[0].functionSelectors, hookPkg.SE_FACET().facetFuncs());
        _assertSelectorEq(cuts[1].functionSelectors, hookPkg.DEPOSIT_FACET().facetFuncs());
        _assertSelectorEq(cuts[2].functionSelectors, hookPkg.WITHDRAW_FACET().facetFuncs());
        _assertSelectorEq(cuts[3].functionSelectors, erc20Facet.facetFuncs());
        _assertSelectorEq(cuts[4].functionSelectors, erc5267Facet.facetFuncs());
        _assertSelectorEq(cuts[5].functionSelectors, erc2612Facet.facetFuncs());
        _assertSelectorEq(cuts[6].functionSelectors, hookPkg.DEPOSIT_SINGLE_FACET().facetFuncs());
        _assertSelectorEq(cuts[7].functionSelectors, hookPkg.DEPOSIT_PREVIEW_FACET().facetFuncs());
    }

    function test_facetCuts_ne_productionFacetCuts() public view {
        assertTrue(
            keccak256(abi.encode(hookPkg.facetCuts()))
                != keccak256(abi.encode(hookPkg.productionFacetCuts()))
        );
    }

    function test_facetFuncs_isS58() public view {
        bytes4[] memory funcs = IFacet(address(hookPkg)).facetFuncs();
        assertEq(funcs.length, 6);
        assertEq(funcs[0], IHooks.beforeInitialize.selector);
        assertEq(funcs[1], IUniswapV4HookStagedPairInit.deployPair.selector);
        assertEq(funcs[2], IUniswapV4HookStagedPairInit.finalizeInitialization.selector);
        assertEq(funcs[3], IUniswapV4HookStagedPairInit.isPairPoolLive.selector);
        assertEq(funcs[4], IUniswapV4HookStagedPairInit.pairPoolKey.selector);
        assertEq(funcs[5], IUniswapV4HookStagedPairInit.isInitializationFinalized.selector);
    }

    function test_facetName_isInitFacetType() public view {
        assertEq(
            IFacet(address(hookPkg)).facetName(),
            type(UniswapV4SingleStandardExchangeBufferConstantProductHookInitFacet).name
        );
    }

    function test_packageName_unchanged() public view {
        assertEq(
            hookPkg.packageName(),
            type(UniswapV4SingleStandardExchangeBufferConstantProductHookDFPkg).name
        );
    }

    function test_postDeploy_returnsTrue_noInit() public {
        assertTrue(hookPkg.postDeploy(address(0x1)));
    }

    function test_S43_deployAlone_noProductDoors() public {
        (address h, IUniswapV4HookStagedPairInit init, address t0, address t1) = _freshBootstrap();
        assertFalse(init.isPairPoolLive(t0, t1));
        assertFalse(init.isPairPoolLive(t1, t0));
        assertFalse(init.isInitializationFinalized());
        assertTrue(h != address(0));
    }

    function test_S43_deployAlone_vaultConfigWorks() public {
        (address h,,,) = _freshBootstrap();
        IStandardVault(h).vaultConfig();
        assertTrue(_registry().isVault(h));
    }

    function test_S43_deployAlone_initSelectorsExist() public {
        (address h,,,) = _freshBootstrap();
        IDiamondLoupe loupe = IDiamondLoupe(h);
        assertEq(
            loupe.facetAddress(IUniswapV4HookStagedPairInit.deployPair.selector), address(hookPkg)
        );
        assertEq(
            loupe.facetAddress(IUniswapV4HookStagedPairInit.finalizeInitialization.selector),
            address(hookPkg)
        );
        assertEq(loupe.facetAddress(IHooks.beforeInitialize.selector), address(hookPkg));
    }

    function test_S43_deployAlone_productionSelectorsUnmatched() public {
        (address h,,,) = _freshBootstrap();
        IDiamondLoupe loupe = IDiamondLoupe(h);
        assertEq(loupe.facetAddress(IHook.deposit.selector), address(0));
        assertEq(loupe.facetAddress(IStandardExchangeIn.exchangeIn.selector), address(0));
        assertEq(loupe.facetAddress(IHook.currency0.selector), address(0));
        assertEq(loupe.facetAddress(IERC20.transfer.selector), address(0));
    }

    function test_S43_deployAlone_erc165_claimsIERC20() public {
        (address h,,,) = _freshBootstrap();
        assertTrue(IERC165(h).supportsInterface(type(IERC20).interfaceId));
        assertEq(IDiamondLoupe(h).facetAddress(IERC20.transfer.selector), address(0));
    }

    function test_S43_pairPoolKey_alwaysConstructed() public {
        (address h, IUniswapV4HookStagedPairInit init, address t0, address t1) = _freshBootstrap();
        PoolKey memory expected = PairPoolLib.pairKey(t0, t1, 60, IHooks(h));
        PoolKey memory actual = init.pairPoolKey(t0, t1);
        _assertKeyEq(actual, expected);
        _assertKeyEq(init.pairPoolKey(t1, t0), actual);
        assertFalse(init.isPairPoolLive(t0, t1));
    }

    function test_deployPair_emitsOnce() public {
        (address h, IUniswapV4HookStagedPairInit init, address t0, address t1) = _freshBootstrap();
        (address c0, address c1) = t0 < t1 ? (t0, t1) : (t1, t0);
        PoolKey memory key = init.pairPoolKey(t0, t1);
        bytes32 poolId = PoolId.unwrap(key.toId());
        vm.expectEmit(true, true, true, true, h);
        emit IUniswapV4HookStagedPairInit.PairPoolDeployed(h, c0, c1, poolId);
        PoolKey memory returned = init.deployPair(t0, t1);
        _assertKeyEq(returned, key);
        assertTrue(init.isPairPoolLive(t0, t1));
    }

    function test_deployPair_skipIfLive_noEvent() public {
        (, IUniswapV4HookStagedPairInit init, address t0, address t1) = _freshBootstrap();
        PoolKey memory first = init.deployPair(t0, t1);
        vm.recordLogs();
        PoolKey memory second = init.deployPair(t1, t0);
        _assertKeyEq(first, second);
        Vm.Log[] memory logs = vm.getRecordedLogs();
        for (uint256 i; i < logs.length; ++i) {
            assertTrue(logs[i].topics.length == 0 || logs[i].topics[0] != PAIR_POOL_DEPLOYED_TOPIC);
        }
    }

    function test_deployPair_orderIndependent() public {
        (, IUniswapV4HookStagedPairInit init, address t0, address t1) = _freshBootstrap();
        PoolKey memory a = init.deployPair(t1, t0);
        PoolKey memory b = init.deployPair(t0, t1);
        _assertKeyEq(a, b);
        assertTrue(init.isPairPoolLive(t0, t1));
        assertTrue(init.isPairPoolLive(t1, t0));
    }

    function test_deployPair_invalidPairReverts() public {
        (, IUniswapV4HookStagedPairInit init, address t0,) = _freshBootstrap();
        vm.expectRevert(SeTarget.InvalidPoolToken.selector);
        init.deployPair(t0, t0);
        vm.expectRevert(SeTarget.InvalidPoolToken.selector);
        init.deployPair(t0, address(0xB0B0));
        vm.expectRevert(SeTarget.InvalidPoolToken.selector);
        init.deployPair(address(0), t0);
        vm.expectRevert(SeTarget.InvalidPoolToken.selector);
        init.deployPair(address(rawToken), address(pairToken));
    }

    function test_finalize_revertsMissingDoors() public {
        (, IUniswapV4HookStagedPairInit init,,) = _freshBootstrap();
        vm.expectRevert(IUniswapV4HookStagedPairInit.ProductDoorsNotLive.selector);
        init.finalizeInitialization();
    }

    function test_finalize_success_returnsTrue() public {
        (address h, IUniswapV4HookStagedPairInit init, address t0, address t1) = _freshBootstrap();
        init.deployPair(t0, t1);

        IDiamond.FacetCut[] memory cuts = _expectedFinalizeCuts();
        vm.expectEmit(false, false, false, true, h);
        emit IDiamond.DiamondCut(cuts, address(0), "");
        vm.expectEmit(true, false, false, true, h);
        emit IUniswapV4HookStagedPairInit.InitializationFinalized(h);
        bool ok = init.finalizeInitialization();
        assertTrue(ok);
    }

    function test_finalize_removesInit_addsProduction() public {
        (address h, IUniswapV4HookStagedPairInit init, address t0, address t1) = _freshBootstrap();
        init.deployPair(t0, t1);
        assertTrue(init.finalizeInitialization());

        IDiamondLoupe loupe = IDiamondLoupe(h);
