                address(token1),
                address(token2),
                uint256(1 ether),
                uint256(0),
                block.timestamp + 1 days
            )
        );
        assertEq(abi.decode(ret, (uint256)), pred);
    }

    function test_D89_ownerDepositSingle_atMin_lpOutGt0() public {
        _ownerSeedBook();
        uint256 lp = IERC20(hook).balanceOf(owner);
        uint256[] memory mins = new uint256[](4);
        vm.prank(owner);
        quad.exitProportional(lp, owner, mins, block.timestamp + 1 days);
        assertEq(IERC20(hook).totalSupply(), 1000, "MIN remains");

        uint256 joinAmt = token1.balanceOf(hook) / 4;
        if (joinAmt == 0) joinAmt = 1;
        vm.expectRevert();
        vm.prank(user);
        quad.depositSingle(address(token1), joinAmt, user, 0, block.timestamp + 1 days);

        vm.prank(owner);
        uint256 lpOut = quad.depositSingle(address(token1), joinAmt, owner, 0, block.timestamp + 1 days);
        assertGt(lpOut, 0, "owner MIN depositSingle lpOut > 0");
