} from "contracts/hooks/uniswap/v4/standardExchange/weighted/interfaces/IUniswapV4StandardExchangeWeightedBufferHookPackage.sol";

/**
 * @notice H1–H2 deploy + binding rejects; n∈{2,3,4} doors.
 */
contract UniswapV4StandardExchangeWeightedBufferHook_Deploy is TestBase {
    /// @notice Every component deployed by the package fits the EIP-170 runtime limit.
    function test_releaseComponents_fitEip170() public view {
        assertGt(address(hookPkg).code.length, 0, "package deployed");
        assertLe(address(hookPkg).code.length, 24_576, "package runtime exceeds EIP-170");
