pragma solidity ^0.8.0;

import {IERC20} from "@crane/contracts/interfaces/IERC20.sol";
import {IUniswapV4SeBufferHook} from "contracts/hooks/uniswap/v4/interfaces/IUniswapV4SeBufferHook.sol";
import {IDETFNFTVault} from "contracts/interfaces/IDETFNFTVault.sol";
import {IStandardExchange} from "contracts/interfaces/IStandardExchange.sol";
import {IUniswapV4Detf} from
    "contracts/vaults/detf/protocols/dexes/uniswap/v4/detf/interfaces/IUniswapV4Detf.sol";
import {UniswapV4DetfRepo} from
    "contracts/vaults/detf/protocols/dexes/uniswap/v4/detf/UniswapV4DetfRepo.sol";
import {TestBase_UniswapV4Detf} from
    "contracts/vaults/detf/protocols/dexes/uniswap/v4/detf/TestBase_UniswapV4Detf.sol";

/// @notice T7.12 Default close: basket, no swaps; DETF min slot 0.
contract UniswapV4Detf_Close is TestBase_UniswapV4Detf {
    /// @notice A custom close cannot pay the holder unrelated tokens already on the DETF.
    function test_E6_customClose_doesNotPayPriorSettlementInventory() public {
        IUniswapV4Detf.PkgArgs memory args = _defaultDetfArgs();
        args.name = "CustomCloseInventory";
        args.closeRouteMode = IUniswapV4Detf.RouteTableMode.Custom;
        args.closeRoutes = new IUniswapV4Detf.IoRoute[](1);
        args.closeRoutes[0] = IUniswapV4Detf.IoRoute({
            token: IERC20(address(pairToken)), vault: IStandardExchange(se)
        });
        IUniswapV4Detf info = IUniswapV4Detf(_deployHookThenDetf(args));
        vm.startPrank(detfUser);
        pairToken.approve(address(info), type(uint256).max);
        (uint256 tokenId,) = info.bond(
            IERC20(address(pairToken)), 100 ether, DEFAULT_MIN_LOCK, detfUser,
            false, block.timestamp + 1 hours
        );
        info.mint(IERC20(address(pairToken)), 20 ether, 0, detfUser, false, block.timestamp + 1 hours);
        vm.stopPrank();
        vm.warp(block.timestamp + DEFAULT_MIN_LOCK + 1);

        uint256 checkpoint = vm.snapshotState();
        vm.prank(detfUser);
        uint256[] memory clean = info.closeBondMature(
            tokenId, new uint256[](1), detfUser, block.timestamp + 1 hours
        );
        assertTrue(vm.revertToState(checkpoint));

        address donor = makeAddr("unrelatedInventoryDonor");
        pairToken.mint(donor, 10 ether);
        vm.prank(donor);
        pairToken.transfer(address(info), 10 ether);
        uint256 before = pairToken.balanceOf(detfUser);
        vm.prank(detfUser);
        uint256[] memory funded = info.closeBondMature(
            tokenId, new uint256[](1), detfUser, block.timestamp + 1 hours
        );
        assertEq(funded[0], clean[0], "unrelated settlement inventory is not close proceeds");
        assertEq(pairToken.balanceOf(detfUser) - before, clean[0], "holder receives only close proceeds");
    }

    /// @notice An unrelated caller cannot retire a holder's mature bond or redirect its assets.
    function test_closeBondMature_rejectsUnrelatedCaller() public {
        uint256 tokenId = _prepareMatureClose();
        address attacker = makeAddr("unauthorizedBondCloser");
        IDETFNFTVault nft = IDETFNFTVault(detfInfo.bondNftVault());
        uint256 originalShares = nft.originalSharesOf(tokenId);
        uint256[] memory minimums = new uint256[](IUniswapV4SeBufferHook(reserveHook).tokens().length);

        vm.expectRevert(abi.encodeWithSelector(UniswapV4DetfRepo.NotAuthorized.selector, attacker));
        vm.prank(attacker);
        detfInfo.closeBondMature(tokenId, minimums, attacker, block.timestamp + 1 hours);

        assertEq(nft.ownerOf(tokenId), detfUser, "holder retains bond");
        assertEq(nft.originalSharesOf(tokenId), originalShares, "principal unchanged");
        assertEq(pairToken.balanceOf(attacker), 0, "no stolen pair capital");
        assertEq(IERC20(detf).balanceOf(attacker), 0, "no stolen rewards");
    }

    /// @notice Transferring the NFT revokes the former holder's right to close it.
    function test_closeBondMature_rejectsFormerHolder() public {
        uint256 tokenId = _prepareMatureClose();
        address newHolder = makeAddr("newBondHolder");
        IDETFNFTVault nft = IDETFNFTVault(detfInfo.bondNftVault());
        vm.prank(detfUser);
        nft.transferFrom(detfUser, newHolder, tokenId);
        uint256[] memory minimums = new uint256[](IUniswapV4SeBufferHook(reserveHook).tokens().length);

        vm.expectRevert(abi.encodeWithSelector(UniswapV4DetfRepo.NotAuthorized.selector, detfUser));
        vm.prank(detfUser);
        detfInfo.closeBondMature(tokenId, minimums, detfUser, block.timestamp + 1 hours);

        assertEq(nft.ownerOf(tokenId), newHolder, "new holder retains bond");
    }

    /// @notice The current holder can close a transferred bond to a chosen recipient.
    function test_closeBondMature_currentHolderCanChooseRecipient() public {
        uint256 tokenId = _prepareMatureClose();
        address newHolder = makeAddr("newBondHolder");
        address recipient = makeAddr("chosenBondRecipient");
        IDETFNFTVault nft = IDETFNFTVault(detfInfo.bondNftVault());
        vm.prank(detfUser);
        nft.transferFrom(detfUser, newHolder, tokenId);
        address[] memory tokens = IUniswapV4SeBufferHook(reserveHook).tokens();

        vm.prank(newHolder);
        uint256[] memory paid = detfInfo.closeBondMature(
            tokenId, new uint256[](tokens.length), recipient, block.timestamp + 1 hours
        );
        uint256 pairPaid;
        for (uint256 i; i < tokens.length; ++i) {
            if (tokens[i] == address(pairToken)) pairPaid = paid[i];
        }
        assertGt(pairPaid, 0, "mature principal paid");
        assertEq(pairToken.balanceOf(recipient), pairPaid, "chosen recipient receives principal");
        assertEq(nft.originalSharesOf(tokenId), 0, "authorized close retires bond");
    }

    function _prepareMatureClose() internal returns (uint256 tokenId) {
        (tokenId,) = _firstBond(100 ether);
        vm.prank(detfUser);
        detfInfo.mint(IERC20(address(pairToken)), 20 ether, 0, detfUser, false, block.timestamp + 1 hours);
        vm.warp(block.timestamp + DEFAULT_MIN_LOCK + 1);
    }

    function test_T7_12_defaultClose_basket_pairOut() public {
        (uint256 tokenId, uint256 shares) = _firstBond(100 ether);
        assertGt(tokenId, 0, "tokenId");
        assertGt(shares, 0, "lp");
        // Leave unassigned LP on the NFT so the hook stays live after this bond's LP exits.
        vm.startPrank(detfUser);
        detfInfo.mint(
            IERC20(address(pairToken)),
            20 ether,
            0,
            detfUser,
            false,
            block.timestamp + 1 hours
        );
        vm.stopPrank();
        address[] memory toks = IUniswapV4SeBufferHook(reserveHook).tokens();
        assertEq(toks[0], detf, "DETF index 0");

        vm.warp(block.timestamp + DEFAULT_MIN_LOCK + 1);
        uint256[] memory minOut = new uint256[](toks.length);
        uint256 pairBefore = IERC20(address(pairToken)).balanceOf(detfUser);

        vm.prank(detfUser);
        uint256[] memory paid = detfInfo.closeBondMature(
            tokenId, minOut, detfUser, block.timestamp + 1 hours
        );

        assertEq(paid.length, toks.length, "tokens() order");
        assertEq(paid[0], 0, "DETF slot not paid to user");
        uint256 pairPaid;
        for (uint256 i; i < toks.length; ++i) {
            if (toks[i] == address(pairToken)) pairPaid = paid[i];
        }
        assertGt(pairPaid, 0, "pair basket leg");
        assertEq(
            IERC20(address(pairToken)).balanceOf(detfUser) - pairBefore,
            pairPaid,
            "user received pair"
        );
        IDETFNFTVault nft = IDETFNFTVault(detfInfo.bondNftVault());
        assertEq(nft.originalSharesOf(tokenId), 0, "position retired");
        _assertNoJoinableDust();
    }
}

