/// @notice N10 accounting regressions through real manager/factory deployed products.
/// @dev No owner impersonation, NFT/LP storage edits, or mocked product calls.
abstract contract UniswapV4Detf_OriginalPrincipalBase is Test {
    address internal constant BONDER = address(0xA110CE);

    struct PrincipalBook {
        uint256 lp;
        uint256 original;
        uint256 protocol;
    }

    struct ClaimMintSnapshot {
        uint256 original;
        uint256 shares;
        uint256 balance;
    }

    function _principalDetf() internal view virtual returns (IUniswapV4Detf);

    function _principalNft() internal view returns (IDETFNFTVault) {
        return IDETFNFTVault(_principalDetf().bondNftVault());
    }

    function _principalBook() internal view returns (PrincipalBook memory b) {
        IDETFNFTVault nft = _principalNft();
        b.lp = IERC20(_principalDetf().hook()).balanceOf(address(nft));
        b.original = nft.totalOriginalShares();
        b.protocol = nft.originalSharesOf(nft.detfNFTId());
    }

    function _principalExpected(uint256 lp, PrincipalBook memory b) internal pure returns (uint256) {
        if (b.original == 0 || b.lp == 0) return lp;
        return BetterMath._convertToSharesDown(lp, b.lp, b.original, 0);
    }

    function _principalLead() internal view returns (IERC20) {
        address d = address(_principalDetf());
        address[] memory tokens = IUniswapV4SeBufferHook(_principalDetf().hook()).tokens();
        for (uint256 i; i < tokens.length; ++i) {
            if (tokens[i] != d) return IERC20(tokens[i]);
        }
        revert("missing pair");
    }

    function _principalBond(uint256 amount, uint256 duration) internal returns (uint256 id, uint256 lp) {
        IUniswapV4Detf d = _principalDetf();
        address[] memory tokens = IUniswapV4SeBufferHook(d.hook()).tokens();
        for (uint256 i; i < tokens.length; ++i) {
            if (tokens[i] == address(d)) continue;
            SimpleMintableERC20(tokens[i]).mint(BONDER, amount * 10);
            vm.prank(BONDER);
            IERC20(tokens[i]).approve(address(d), type(uint256).max);
        }
        IERC20 lead = _principalLead();
        vm.prank(BONDER);
        return d.bond(lead, amount, duration, BONDER, false, block.timestamp + 1 hours);
    }

    function _principalDonate() internal {
        IDETFNFTVault nft = _principalNft();
        IERC20 lead = _principalLead();
        SimpleMintableERC20(address(lead)).mint(BONDER, 40 ether);
        uint256 original = nft.totalOriginalShares();
        vm.startPrank(BONDER);
        lead.approve(address(nft), 40 ether);
        uint256 lp = IDetfNftReserveDonation(address(nft)).donate(lead, 40 ether, 0, false, block.timestamp + 1 hours);
        vm.stopPrank();
        assertGt(lp, 0, "donation joined");
        assertEq(nft.totalOriginalShares(), original, "R12a gift is unassigned");
    }

    function _principalClose(uint256 id) internal {
        IUniswapV4Detf d = _principalDetf();
        vm.warp(_principalNft().unlockTimeOf(id) + 1);
        uint256[] memory mins = new uint256[](IUniswapV4SeBufferHook(d.hook()).tokens().length);
        vm.prank(BONDER);
        d.closeBondMature(id, mins, BONDER, block.timestamp + 1 hours);
    }

    function _principalSeedProtocol() internal returns (uint256 survivor) {
        (survivor,) = _principalBond(100 ether, 30 days);
        (uint256 closed,) = _principalBond(20 ether, 30 days);
        _principalClose(closed);
        assertGt(_principalBook().protocol, 0, "ordinary close established id0");
        _principalDonate();
    }

    /// @notice A subsequent bond buys original principal at pre-join NAV after an R12a gift.
    function test_P1_laterBond_creditsOriginalPrincipal_afterDonation() public {
        uint256 survivor = _principalSeedProtocol();
        IDETFNFTVault nft = _principalNft();
        PrincipalBook memory before = _principalBook();
        uint256 oldPrincipal = nft.originalSharesOf(survivor);
        uint256 oldAssets = nft.convertToAssets(oldPrincipal);
        (uint256 id, uint256 lp) = _principalBond(10 ether, 180 days);
        uint256 expected = _principalExpected(lp, before);
        assertLt(expected, lp, "gift makes LP and originals distinct");
        assertEq(nft.originalSharesOf(id), expected, "credit uses pre-join originals");
        assertEq(nft.effectiveSharesOf(id), expected * 15 / 10, "lock bonus applies to converted principal");
        assertEq(nft.effectiveSharesOf(survivor), oldPrincipal, "distinct reward weight on old bond");
        assertGe(nft.convertToAssets(oldPrincipal) + 2, oldAssets, "new bond preserves prior LP entitlement");
    }

    /// @notice Public reward compounding returns physical LP and books converted id0 originals.
    function test_P1_compound_creditsOriginalPrincipal_afterDonation() public {
        uint256 survivor = _principalSeedProtocol();
        IUniswapV4Detf d = _principalDetf();
        IDETFNFTVault nft = _principalNft();
        uint256 reward = IERC20(address(d)).balanceOf(BONDER) / 4;
        assertGt(reward, 0, "real bond minted transferable DETF");
        vm.prank(BONDER);
        IERC20(address(d)).transfer(address(nft), reward);
        PrincipalBook memory before = _principalBook();
        uint256 oldAssets = nft.convertToAssets(nft.originalSharesOf(survivor));
        (uint256 used, uint256 lp) = d.compoundProtocolRewards();
        assertGt(used, 0, "ordinary rewards compound");
        assertGt(lp, 0, "compound physically joins LP");
        assertEq(
            nft.originalSharesOf(nft.detfNFTId()) - before.protocol,
            _principalExpected(lp, before),
            "compound original credit"
        );
        assertGe(
            nft.convertToAssets(nft.originalSharesOf(survivor)) + 2, oldAssets, "compound preserves user principal"
        );
    }

    /// @notice Close's DETF surplus is priced after retiring and withdrawing the closed principal.
    function test_P1_closeRejoin_creditsOriginalPrincipal_afterDonation() public {
        _principalSeedProtocol();
        (uint256 id,) = _principalBond(10 ether, 30 days);
        IDETFNFTVault nft = _principalNft();
        PrincipalBook memory before = _principalBook();
        uint256 retired = nft.originalSharesOf(id);
        before.lp -= nft.convertToAssets(retired);
        before.original -= retired;
        vm.recordLogs();
        _principalClose(id);
        Vm.Log[] memory logs = vm.getRecordedLogs();
        uint256 joined = _principalFirstLpMint(logs, address(nft));
        assertGt(joined, 0, "close surplus rejoins physical LP");
        assertEq(
            nft.originalSharesOf(nft.detfNFTId()) - before.protocol,
            _principalExpected(joined, before),
            "close rejoin uses remaining principal NAV"
        );
    }

    function _principalFirstLpMint(Vm.Log[] memory logs, address nft) internal view returns (uint256) {
        address hook = _principalDetf().hook();
        for (uint256 i; i < logs.length; ++i) {
            if (
                logs[i].emitter == hook && logs[i].topics.length == 3
                    && logs[i].topics[0] == keccak256("Transfer(address,address,uint256)")
                    && logs[i].topics[1] == bytes32(0) && logs[i].topics[2] == bytes32(uint256(uint160(nft)))
            ) {
                return abi.decode(logs[i].data, (uint256));
            }
        }
        revert("missing LP mint");
    }

    /// @notice Claim purchases use the same converted originals for NFT and claim-share issuance.
    function test_P1_buyClaim_creditsOriginalPrincipal_afterDonation() public {
        _principalBond(100 ether, 30 days);
        _principalDonate();
        IUniswapV4Detf d = _principalDetf();
        IDETFNFTVault nft = _principalNft();
        IRebasingClaimToken claim = IRebasingClaimToken(d.rebasingClaimToken());
        uint256 amount = IERC20(address(d)).balanceOf(BONDER) / 10;
        PrincipalBook memory before = _principalBook();
        assertEq(before.protocol, 0, "first claim issuance has no unrepresented id0 principal");
        assertEq(claim.totalShares(), 0, "first claim issuance");
        vm.recordLogs();
        uint256 minted = _principalBuyClaim(amount, 1);
        Vm.Log[] memory logs = vm.getRecordedLogs();
        // Principal issuance uses the actual LP join, not a family hook preview.
        uint256 expected = _principalExpected(_principalFirstLpMint(logs, address(nft)), before);
        ClaimMintSnapshot memory issuance = _principalClaimMintEvent(logs, address(claim));
        assertEq(issuance.original, expected, "mint event original units use actual pre-join conversion");
        assertEq(issuance.shares, expected, "mint event first share issuance uses original units");
        assertEq(issuance.balance, minted, "returned balance matches issuance event snapshot");
        assertEq(nft.originalSharesOf(nft.detfNFTId()), expected, "claim purchase credits original units");
        assertEq(claim.sharesOf(BONDER), expected, "first claim share issuance uses original units");
        assertGt(minted, 0, "first purchase returns a nonzero rebasing balance");
        // End-of-call maintenance can add unassigned LP after the mint event.
        // Shares stay fixed while the balance reflects the updated reserve NAV.
        assertEq(claim.balanceOf(BONDER), Math.mulDiv(expected, claim.redemptionRate(), 1e18), "final balance uses live NAV");
        assertGe(claim.balanceOf(BONDER), minted, "final maintenance preserves the issued balance minimum");
    }

    function _principalClaimMintEvent(Vm.Log[] memory logs, address claim)
        internal
        pure
        returns (ClaimMintSnapshot memory issuance)
    {
        for (uint256 i; i < logs.length; ++i) {
            if (logs[i].emitter == claim && logs[i].topics.length == 2
                && logs[i].topics[0] == keccak256("Minted(address,uint256,uint256,uint256)")
                && logs[i].topics[1] == bytes32(uint256(uint160(BONDER)))) {
                return abi.decode(logs[i].data, (ClaimMintSnapshot));
            }
        }
        revert("missing claim mint event");
    }

    function _principalBuyClaim(uint256 amount, uint256 minimum) internal returns (uint256 minted) {
        address d = address(_principalDetf());
        IERC20 claim = IERC20(_principalDetf().rebasingClaimToken());
        vm.startPrank(BONDER);
        IERC20(d).approve(d, amount);
        minted = IStandardExchangeIn(d)
            .exchangeIn(IERC20(d), amount, claim, minimum, BONDER, false, block.timestamp + 1 hours);
        vm.stopPrank();
    }

    /// @notice A failed claim minimum rolls back the join, NFT credit, claim mint, and token pull.
    function test_P1_buyClaim_minimum_revertsEntireOriginalCredit() public {
        _principalBond(100 ether, 30 days);
        _principalDonate();
        IUniswapV4Detf d = _principalDetf();
        IRebasingClaimToken claim = IRebasingClaimToken(d.rebasingClaimToken());
        PrincipalBook memory before = _principalBook();
        uint256 tokenBefore = IERC20(address(d)).balanceOf(BONDER);
        uint256 supplyBefore = IERC20(d.hook()).totalSupply();
        uint256 amount = tokenBefore / 10;
        uint256 snapshot = vm.snapshotState();
        uint256 minted = _principalBuyClaim(amount, 0);
        assertTrue(vm.revertToStateAndDelete(snapshot), "restore identical pre-purchase state");
        uint256 minimum = minted + 1;
        _principalRejectClaimMinimum(amount, minimum, minted);
        PrincipalBook memory afterBook = _principalBook();
        assertEq(afterBook.lp, before.lp, "physical LP rolled back");
        assertEq(afterBook.original, before.original, "NFT original credit rolled back");
        assertEq(afterBook.protocol, before.protocol, "id0 credit rolled back");
        assertEq(claim.totalShares(), 0, "claim share mint rolled back");
        assertEq(claim.balanceOf(BONDER), 0, "claim balance rolled back");
        assertEq(IERC20(address(d)).balanceOf(BONDER), tokenBefore, "DETF pull rolled back");
        assertEq(IERC20(d.hook()).totalSupply(), supplyBefore, "hook LP mint rolled back");
    }

    function _principalRejectClaimMinimum(uint256 amount, uint256 minimum, uint256 minted) internal {
        address d = address(_principalDetf());
        IERC20 claim = IERC20(_principalDetf().rebasingClaimToken());
        vm.startPrank(BONDER);
        IERC20(d).approve(d, amount);
        vm.expectRevert(abi.encodeWithSelector(IStandardExchangeErrors.MinAmountNotMet.selector, minimum, minted));
        IStandardExchangeIn(d)
            .exchangeIn(
                IERC20(d),
                amount,
                claim,
                minimum,
                BONDER,
                false,
                block.timestamp + 1 hours
            );
        vm.stopPrank();
    }
}

/// @notice CP binding uses the production manager/factory fixture.
contract UniswapV4Detf_OriginalPrincipal is TestBase_UniswapV4Detf, UniswapV4Detf_OriginalPrincipalBase {
    function _principalDetf() internal view override returns (IUniswapV4Detf) {
        return detfInfo;
    }

    /// @notice Unassigned LP from an ordinary mint cannot let a sub-share bond dilute existing principal.
    function test_P1_tinyPrincipal_belowShareBond_revertsAtomically() public {
        uint256 survivor = _tinyPrincipalWithUnassignedGrowth();
        uint256 amount = _tinyOneShareBondAmount() / 2;
        uint256 lp = _tinyPreviewBondLp(amount);
        IDETFNFTVault nft = _principalNft();
        PrincipalBook memory before = _principalBook();
        assertGt(lp, 0, "hook would issue physical LP");
        assertEq(_principalExpected(lp, before), 0, "deposit is below one original share");
        assertEq(nft.convertToShares(lp), 0, "NFT preview uses the same floor");
        uint256 assets = nft.convertToAssets(nft.originalSharesOf(survivor));
        _tinyApprovePair(amount);
        uint256 pairBefore = _principalLead().balanceOf(BONDER);
        IERC20 lead = _principalLead();
        uint256 detfSupply = IERC20(detf).totalSupply();
        uint256 positions = nft.balanceOf(BONDER);

        vm.prank(BONDER);
        vm.expectRevert(UniswapV4DetfRepo.ZeroAmount.selector);
        detfInfo.bond(lead, amount, 30 days, BONDER, false, block.timestamp + 1 hours);

        assertEq(_principalLead().balanceOf(BONDER), pairBefore, "token pull rolled back");
        assertEq(IERC20(detf).totalSupply(), detfSupply, "bond mint rolled back");
        assertEq(nft.balanceOf(BONDER), positions, "no zero-principal NFT");
        assertEq(_principalBook().lp, before.lp, "LP join rolled back");
        assertEq(nft.totalOriginalShares(), before.original, "principal supply unchanged");
        assertEq(nft.convertToAssets(nft.originalSharesOf(survivor)), assets, "prior holder unchanged");
    }

    /// @notice Even a positive hook LP quote cannot authorize zero-original claim issuance.
    function test_P1_tinyPrincipal_belowShareClaimPurchase_revertsAtomically() public {
        _tinyPrincipalWithUnassignedGrowth();
        PrincipalBook memory before = _principalBook();
        (uint256 amount, uint256 lp) = _tinySubShareClaimAmount();
        assertGt(lp, 0, "positive DETF input buys physical LP");
        assertEq(_principalExpected(lp, before), 0, "LP buys no original share");
        uint256 balanceBefore = IERC20(detf).balanceOf(BONDER);
        assertGe(balanceBefore, amount, "ordinary bond/mint funded buyer");
        address claim = detfInfo.rebasingClaimToken();
        vm.startPrank(BONDER);
        IERC20(detf).approve(detf, amount);
        vm.expectRevert(UniswapV4DetfRepo.ZeroAmount.selector);
        IStandardExchangeIn(detf)
            .exchangeIn(IERC20(detf), amount, IERC20(claim), 0, BONDER, false, block.timestamp + 1 hours);
        vm.stopPrank();

        assertEq(IERC20(detf).balanceOf(BONDER), balanceBefore, "claim purchase pull rolled back");
        assertEq(_principalBook().lp, before.lp, "claim purchase join rolled back");
        assertEq(_principalNft().totalOriginalShares(), before.original, "no original credit");
        assertEq(IRebasingClaimToken(claim).totalShares(), 0, "no claim mint");
    }

    /// @notice A representable deposit floors principal and cannot reduce prior LP entitlement.
    function test_P1_tinyPrincipal_aboveShareBond_floorsWithoutDilution() public {
        uint256 survivor = _tinyPrincipalWithUnassignedGrowth();
        uint256 amount = _tinyOneShareBondAmount();
        PrincipalBook memory before = _principalBook();
        IDETFNFTVault nft = _principalNft();
        uint256 assetsBefore = nft.convertToAssets(nft.originalSharesOf(survivor));
        (uint256 id, uint256 lp) = _principalBond(amount, 30 days);
        uint256 expected = _principalExpected(lp, before);
        assertEq(expected, 1, "one representable original share");
        assertLt(expected, BetterMath._convertToSharesUp(lp, before.lp, before.original, 0), "ceil overcredits");
        assertEq(nft.originalSharesOf(id), expected, "deposit floors original credit");
        assertGe(nft.convertToAssets(nft.originalSharesOf(survivor)), assetsBefore, "no prior-holder dilution");
    }

    /// @notice Mature close remains live when its returned DETF rejoins less than one original share.
    function test_P1_tinyPrincipal_closeRejoin_belowShareRemainsUnassigned() public {
        uint256 survivor = _tinyPrincipalWithUnassignedGrowth();
        (uint256 closed,) = _principalBond(_tinyOneShareBondAmount(), 30 days);
        IDETFNFTVault nft = _principalNft();
        PrincipalBook memory before = _principalBook();
        uint256 retired = nft.originalSharesOf(closed);
        assertEq(retired, 1, "close one original share");
        uint256 oldPrincipal = nft.originalSharesOf(survivor);
        uint256 oldAssets = nft.convertToAssets(oldPrincipal);
        _tinyAssertCloseRawAmount(nft.convertToAssets(retired));
        before.lp -= nft.convertToAssets(retired);
        before.original -= retired;
        vm.recordLogs();
        _principalClose(closed);
        Vm.Log[] memory logs = vm.getRecordedLogs();
        uint256 joined = _principalFirstLpMint(logs, address(nft));
        _tinyAssertNonzeroRawZap(logs);

        assertGt(joined, 0, "close returned physical LP to custody");
        assertEq(_principalExpected(joined, before), 0, "rejoin is below an original share");
        assertEq(nft.originalSharesOf(closed), 0, "close retired the user position");
        assertEq(nft.totalOriginalShares(), before.original, "no whole-share overcredit");
        assertEq(nft.originalSharesOf(nft.detfNFTId()), before.protocol, "sub-share LP stays unassigned");
        assertGe(nft.convertToAssets(oldPrincipal), oldAssets, "remaining holder keeps principal");
    }

    /// @notice An unrepresentable compound preserves id-0 pending rewards instead of gifting them away.
    function test_P1_tinyPrincipal_compoundBelowShare_preservesPendingRewards() public {
        _tinyPrincipalWithUnassignedGrowth();
        _principalBuyClaim(_tinyRepresentableClaimAmount(), 0);
        IDETFNFTVault nft = _principalNft();
        uint256 id0 = nft.detfNFTId();
        assertEq(nft.pendingRewards(id0), 0, "new protocol principal has no old rewards");
        uint256 effective = nft.effectiveSharesOf(id0);
        assertGt(effective, 0, "claim purchase established id0");
        // Invert the production reward accumulator's two floors to allocate two wei.
        uint256 perShare = (2e18 + effective - 1) / effective;
        uint256 reward = (perShare * nft.totalShares() + 1e18 - 1) / 1e18;
        assertGe(IERC20(detf).balanceOf(BONDER), reward, "real free DETF funds reward pot");
        vm.prank(BONDER);
        IERC20(detf).transfer(address(nft), reward);
        uint256 pending = nft.pendingRewards(id0);
        assertEq(pending, 2, "pending crosses the compound dust gate");
        PrincipalBook memory before = _principalBook();
        uint256 lp = IUniswapV4SeBufferHook(detfInfo.hook()).previewJoinSingleAssetExactIn(detf, pending);
        assertGt(lp, 0, "reward can join LP");
        assertEq(_principalExpected(lp, before), 0, "reward cannot buy original principal");
        uint256 rewardBalance = IERC20(detf).balanceOf(address(nft));

        (uint256 used, uint256 joined) = detfInfo.compoundProtocolRewards();

        assertEq(used, 0, "best-effort compound skipped");
        assertEq(joined, 0, "atomic join rolled back");
        assertEq(nft.pendingRewards(id0), pending, "protocol retains pending rewards");
        assertEq(IERC20(detf).balanceOf(address(nft)), rewardBalance, "reward custody preserved");
        assertEq(_principalBook().lp, before.lp, "LP custody unchanged");
        assertEq(nft.totalOriginalShares(), before.original, "no whole-share overcredit");
    }

    function _tinyPrincipalWithUnassignedGrowth() private returns (uint256 survivor) {
        // Just above the hook's locked minimum: leaves a small positive original
        // supply and enough raw reserve per original for a nonzero close zap.
        (survivor,) = _principalBond(1_500, 30 days);
        PrincipalBook memory before = _principalBook();
        assertGt(before.original, 0, "small live bootstrap");
        assertLe(before.original, 1_500, "small principal supply");
        uint256 amount = 40 ether;
        _tinyApprovePair(amount);
        IERC20 lead = _principalLead();
        vm.prank(BONDER);
        detfInfo.mint(lead, amount, 0, BONDER, false, block.timestamp + 1 hours);
        PrincipalBook memory afterBook = _principalBook();
        assertEq(afterBook.original, before.original, "live mint adds unassigned LP");
        assertGt(afterBook.lp, before.lp, "ordinary mint grows physical backing");
        assertGt(afterBook.lp / afterBook.original, 1_000, "normal mint creates material LP/share ratio");
    }

    function _tinyApprovePair(uint256 amount) private {
        IERC20 lead = _principalLead();
        SimpleMintableERC20(address(lead)).mint(BONDER, amount);
        vm.prank(BONDER);
        lead.approve(detf, amount);
    }

    function _tinyPairPerOriginal() private view returns (uint256) {
        IUniswapV4SeBufferHook hook = IUniswapV4SeBufferHook(detfInfo.hook());
        address[] memory tokens = hook.tokens();
        uint256[] memory amounts = hook.previewExitProportional(IERC20(address(hook)).totalSupply());
        for (uint256 i; i < tokens.length; ++i) {
            if (tokens[i] != detf) return amounts[i] / (_principalNft().totalOriginalShares() + 1);
        }
        revert("missing pair reserve");
    }

    function _tinyPreviewBondLp(uint256 amount) private view returns (uint256) {
        IUniswapV4SeBufferHook hook = IUniswapV4SeBufferHook(detfInfo.hook());
        address[] memory tokens = hook.tokens();
        uint256[] memory reserves = hook.previewExitProportional(IERC20(address(hook)).totalSupply());
        uint256 pairReserve;
        uint256 detfReserve;
        for (uint256 i; i < tokens.length; ++i) {
            if (tokens[i] == detf) detfReserve = reserves[i];
            else pairReserve = reserves[i];
        }
        uint256 g = detfReserve * amount / pairReserve;
        if (g == 0) g = amount; // The fixture's creation rate is 1e18.
        address[] memory joinTokens = new address[](2);
        uint256[] memory joinAmounts = new uint256[](2);
        joinTokens[0] = detf;
        joinTokens[1] = address(_principalLead());
        joinAmounts[0] = g;
        joinAmounts[1] = amount;
        return hook.previewJoinUnbalanced(joinTokens, joinAmounts);
    }

    function _tinyOneShareBondAmount() private view returns (uint256) {
        PrincipalBook memory book = _principalBook();
        uint256 high = _tinyPairPerOriginal();
        assertGt(high, 0, "live pair reserve represents original principal");
        while (_principalExpected(_tinyPreviewBondLp(high), book) == 0) high *= 2;
        uint256 low;
        // Find the actual first input that buys one original, then move inside
        // its rounding interval so the old ceil path provably overcredits.
        while (high - low > 1) {
            uint256 mid = low + (high - low) / 2;
            if (_principalExpected(_tinyPreviewBondLp(mid), book) == 0) low = mid;
            else high = mid;
        }
        uint256 amount = high + high / 4;
        uint256 lp = _tinyPreviewBondLp(amount);
        assertEq(_principalExpected(lp, book), 1, "live quote buys exactly one original");
        assertGt(BetterMath._convertToSharesUp(lp, book.lp, book.original, 0), 1, "fractional share boundary");
        return amount;
    }

    function _tinySubShareClaimAmount() private view returns (uint256 amount, uint256 lp) {
        PrincipalBook memory book = _principalBook();
        IUniswapV4SeBufferHook hook = IUniswapV4SeBufferHook(detfInfo.hook());
        // Start above the half-split dust input and require both parts of the
        // intended boundary from the live hook quote, not a guessed LP ratio.
        for (amount = 2; amount <= 64; ++amount) {
            lp = hook.previewJoinSingleAssetExactIn(detf, amount);
            if (lp > 0 && _principalExpected(lp, book) == 0) return (amount, lp);
        }
        revert("no positive sub-share production claim quote");
    }

    function _tinyRepresentableClaimAmount() private view returns (uint256 amount) {
        PrincipalBook memory book = _principalBook();
        IUniswapV4SeBufferHook hook = IUniswapV4SeBufferHook(detfInfo.hook());
        for (amount = 2; amount <= 64; ++amount) {
            if (_principalExpected(hook.previewJoinSingleAssetExactIn(detf, amount), book) > 0) return amount;
        }
        revert("no representable production claim quote");
    }

    function _tinyAssertCloseRawAmount(uint256 lp) private view {
        IUniswapV4SeBufferHook hook = IUniswapV4SeBufferHook(detfInfo.hook());
        address[] memory tokens = hook.tokens();
        uint256[] memory amounts = hook.previewExitProportional(lp);
        for (uint256 i; i < tokens.length; ++i) {
            if (tokens[i] == detf) {
                assertGe(amounts[i], 2, "live close quote avoids zero half-split");
                return;
            }
        }
        revert("missing raw reserve");
    }

    function _tinyAssertNonzeroRawZap(Vm.Log[] memory logs) private view {
        address hook = detfInfo.hook();
        for (uint256 i; i < logs.length; ++i) {
            if (
                logs[i].emitter != hook || logs[i].topics.length != 2
                    || logs[i].topics[0] != keccak256("ZapSwap(address,address,address,uint256,uint256)")
            ) continue;
            (address tokenIn,, uint256 amountIn, uint256 amountOut) =
                abi.decode(logs[i].data, (address, address, uint256, uint256));
            if (tokenIn != detf) continue;
            assertGt(amountIn, 0, "close rejoin sells nonzero raw DETF");
            assertGt(amountOut, 0, "close rejoin receives nonzero pair tokens");
            return;
        }
        revert("missing close raw zap");
    }

}

